  (336, 0, 6, '稀里哗啦！劈里啪啦！', 1097, 1, 0),
  (337, 0, 0, '小心俺的轮子，轧扁了可不负责！', 1098, 1, 0),
  (338, 0, 2, '小心！俺轧过来啦！', 1098, 1, 0),
