INSERT INTO "gamedata"."ov_dialog" ("row_no", "reserve", "scene", "desc_", "mon_id", "speak_grp_1_4", "reserved") VALUES
  (478, 0, 6, '妈呀！我的角！', 1134, 1, 0),
  (479, 0, 0, '敢欺负我们姐妹？活得不耐烦啦？', 1135, 1, 0),
  (48, 0, 2, '我是刑天我怕谁！', 1011, 1, 0),
  (480, 0, 0, '想看我的脸吗？嘻嘻，就不给你看！', 1135, 1, 0),
  (481, 0, 3, '呀呀！呀呀！', 1135, 1, 0),
  (482, 0, 4, '呀呀！呀呀！', 1135, 1, 0),
  (483, 0, 5, '哟嚯！姐妹们，我赢啦！', 1135, 1, 0),
  (484, 0, 6, '丢脸死啦！', 1135, 1, 0),
  (485, 0, 0, '我们面具家族，可是有组织有纪律的！', 1136, 1, 0),
  (486, 0, 2, '好像有危险！', 1136, 1, 0),
  (487, 0, 3, '不准欺负我的面具孩儿们！', 1136, 1, 0),
  (488, 0, 4, '我这张帅脸，不是谁都可以看的', 1136, 1, 0),
  (489, 0, 5, '现在的人也越来越不经打了！', 1136, 1, 0),
  (49, 0, 3, '看我的左勾拳！看我的右勾拳！', 1011, 1, 0),
  (490, 0, 6, '孩儿们替我报仇！', 1136, 1, 0),
  (491, 0, 0, '见过我兄弟吗？它是小小蜗牛怪……', 1137, 1, 0),
  (492, 0, 3, '试试我们蜗牛兄弟的厉害！', 1137, 1, 0),
  (493, 0, 4, '别人都说我很有内涵', 1137, 2, 0),
  (494, 0, 4, '看你的招厉害还是我的壳硬', 1137, 2, 0),
  (495, 0, 5, '再来打过！', 1137, 1, 0),
  (496, 0, 6, '哎唷！', 1137, 1, 0),
  (497, 0, 0, '小小蜗牛怪，越看越可爱，嘻嘻…', 1138, 1, 0),
  (498, 0, 3, '先热热身吧！', 1138, 2, 0),
  (499, 0, 3, '别打我，我是路过的', 1138, 2, 0),
  (5, 0, 0, '嫩嫩的人肉最养颜啦！', 1002, 1, 0),
  (50, 0, 4, '拜托，用点劲儿好不好？', 1011, 1, 0),
  (500, 0, 4, '啦啦啦，我走到哪里都有家', 1138, 2, 0),
  (501, 0, 4, '哎哟！', 1138, 2, 0),
  (502, 0, 5, '看我超强必杀！嘿嘿！', 1138, 1, 0),
  (503, 0, 6, '噢！', 1138, 1, 0),
  (504, 0, 0, '俺大熊可不是好惹的哦！', 1139, 1, 0),
  (505, 0, 3, '吼吼，想吃我一记熊掌吗？', 1139, 1, 0),
  (506, 0, 4, '吼吼，想吃我一记熊掌吗？', 1139, 1, 0),
  (507, 0, 5, '熊掌的味道如何，吼吼？', 1139, 1, 0),
  (508, 0, 6, '我可不想变成红烧熊掌！', 1139, 1, 0),
  (509, 0, 3, '哼!我可是吃肉的', 1140, 1, 0),
  (51, 0, 5, '不怕死的就上！', 1011, 1, 0),
  (510, 0, 4, '小心我咬你哦!', 1140, 1, 0),
  (511, 0, 0, '本鸟一般不和人说话的……', 1141, 1, 0),
  (512, 0, 2, '我好像看到了人！', 1141, 1, 0),
  (513, 0, 3, '好家伙！', 1141, 1, 0),
  (514, 0, 4, '好家伙！', 1141, 1, 0),
  (515, 0, 5, '神鸟可不是吹的！', 1141, 1, 0),
  (516, 0, 6, '不会吧？', 1141, 1, 0),
  (517, 0, 0, '乖乖的，乖乖的……', 1142, 1, 0),
  (518, 0, 4, '欺负我不会动，小心我妈妈收拾你', 1142, 2, 0),
  (519, 0, 4, '不要打我好不好？', 1142, 2, 0),
  (52, 0, 6, '终于来了个厉害的！', 1011, 1, 0),
  (520, 0, 0, '我在天上飞呀，看我的小叉叉呀！', 1143, 1, 0),
  (521, 0, 2, '唷！唷！有人来喽！', 1143, 1, 0),
  (522, 0, 3, '看我的叉叉！', 1143, 2, 0),
  (523, 0, 3, '我这身行头蛮帅', 1143, 2, 0),
  (524, 0, 4, '狗急了跳墙，猪急了能上树', 1143, 1, 0),
  (525, 0, 5, '唷！唷！太棒啦！', 1143, 1, 0),
  (526, 0, 6, '见鬼啰！', 1143, 1, 0),
  (527, 0, 0, '像我这样的天才猴子你见过吗？', 1144, 1, 0),
  (528, 0, 3, '打就打，谁怕谁！', 1144, 1, 0),
  (529, 0, 4, '打就打，谁怕谁！', 1144, 1, 0),
  (53, 0, 0, '今天天气好晴朗，啦啦啦！', 1013, 1, 0),
  (530, 0, 5, '我强我强我最强,嘢嘢!', 1144, 1, 0),
  (531, 0, 6, '死就死，谁怕谁？', 1144, 1, 0),
  (532, 0, 0, '最讨厌那些人乱叫啦～～', 1145, 2, 0),
  (533, 0, 0, '我们不是妖精，我们是精灵！', 1145, 2, 0),
  (534, 0, 3, '呼呼！呼呼！', 1145, 1, 0),
  (535, 0, 4, '呼呼！呼呼！', 1145, 1, 0),
  (536, 0, 5, '精灵不是随便惹的！', 1145, 1, 0),
  (537, 0, 6, '下次再来打过！', 1145, 1, 0),
  (538, 0, 0, '打你，是因为我喜欢你，咯咯！', 1146, 1, 0),
  (539, 0, 3, '疼不疼啊？真让人心疼啊！', 1146, 1, 0),
  (54, 0, 3, '嘿咻！嘿咻！', 1013, 1, 0),
  (540, 0, 4, '哎唷！', 1146, 1, 0),
  (541, 0, 5, '打死你，是因为我喜欢死你啦，咯咯！', 1146, 1, 0),
  (542, 0, 6, '你舍得我死么？', 1146, 1, 0),
  (543, 0, 0, '你打得着我吗？打不着吧？', 1147, 1, 0),
  (544, 0, 3, '打啊！打啊！叫你打不着！', 1147, 1, 0),
  (545, 0, 4, '打啊！打啊！叫你打不着！', 1147, 1, 0),
  (546, 0, 5, '想打到我，没那么容易！', 1147, 1, 0),
  (547, 0, 6, '糟糕！散架啦！', 1147, 1, 0),
  (548, 0, 0, '追啊，有本事你追我啊！', 1148, 1, 0),
  (549, 0, 0, '追啊，有本事你追我啊！', 1148, 1, 0),
  (55, 0, 4, '不要看我小就欺负我！', 1013, 2, 0),
  (550, 0, 3, '别打我嘛！', 1148, 1, 0),
  (551, 0, 4, '敢欺负我，小心我嫦娥姐姐扁你！', 1148, 2, 0),
  (552, 0, 4, '怕怕！快闪！', 1148, 2, 0),
  (553, 0, 5, '嘢！', 1148, 1, 0),
  (554, 0, 6, '救命啊！', 1148, 1, 0),
  (555, 0, 0, '追啊，有本事你追我啊！', 1149, 1, 0),
  (556, 0, 0, '追啊，有本事你追我啊！', 1149, 1, 0),
  (557, 0, 3, '别打我嘛！', 1149, 1, 0),
  (558, 0, 4, '怕怕！快闪！', 1149, 1, 0),
  (559, 0, 5, '嘢！', 1149, 1, 0),
  (56, 0, 4, '想学猫步的跟我来', 1013, 2, 0),
  (560, 0, 6, '救命啊！', 1149, 1, 0),
  (561, 0, 0, '追啊，有本事你追我啊！', 1150, 1, 0),
  (562, 0, 0, '追啊，有本事你追我啊！', 1150, 1, 0),
  (563, 0, 3, '别打我嘛！', 1150, 2, 0),
  (564, 0, 3, '哎呀！你不怕我咬你啊！', 1150, 2, 0),
  (565, 0, 4, '怕怕！快闪！', 1150, 2, 0),
  (566, 0, 4, '敢欺负我，小心嫦娥姐姐扁你哦！', 1150, 2, 0),
  (567, 0, 5, '嘢！', 1150, 1, 0)
INSERT INTO "gamedata"."ov_dialog" ("row_no", "reserve", "scene", "desc_", "mon_id", "speak_grp_1_4", "reserved") VALUES
  (568, 0, 6, '救命啊！', 1150, 1, 0),
  (569, 0, 0, '讨厌讨厌真讨厌！', 1152, 1, 0),
  (57, 0, 5, '挺厉害吧？嘻嘻！', 1013, 1, 0),
  (570, 0, 4, '又来惹我？', 1152, 1, 0),
  (571, 0, 5, '何苦来惹我？', 1152, 1, 0),
  (572, 0, 6, '哎哟，真讨厌！', 1152, 1, 0),
  (573, 0, 0, '真饿啊……', 1153, 1, 0),
  (574, 0, 2, '又有大餐送上门啦！', 1153, 2, 0),
  (575, 0, 2, '其实我是只羊', 1153, 2, 0),
  (576, 0, 3, '我的口水都流出来啦！', 1153, 1, 0),
  (577, 0, 4, '挺厉害的嘛', 1153, 1, 0),
  (578, 0, 5, '我的口水都流出来啦！', 1153, 1, 0),
  (579, 0, 6, '噢－－', 1153, 1, 0),
  (58, 0, 6, '我还不想死呢，呜呜呜……', 1013, 1, 0),
  (580, 0, 0, '陪我玩玩好不好？', 1154, 1, 0),
  (581, 0, 2, '有人陪我玩啦！', 1154, 1, 0),
  (582, 0, 3, '就你这身子板我一刀砍俩', 1154, 2, 0),
  (583, 0, 3, '我轻轻地打你好不好？', 1154, 2, 0),
  (584, 0, 5, '和人打架好好玩！', 1154, 1, 0),
  (585, 0, 6, '一点也不好玩嘛！', 1154, 1, 0),
  (586, 0, 0, '小心哦！我过来了哦！', 1161, 1, 0),
  (587, 0, 2, '小心哦！我过来了哦！', 1161, 1, 0),
  (588, 0, 3, '苍蝇拍，拍拍拍！', 1161, 1, 0),
  (589, 0, 4, '我挡！', 1161, 1, 0),
  (59, 0, 7, '糟糕，打不过！', 1013, 1, 0),
  (590, 0, 5, '这么容易就被拍死啦？', 1161, 1, 0),
  (591, 0, 6, '哎唷！妈呀！', 1161, 1, 0),
  (592, 0, 0, '打架归打架，不要乱扔东西哦！', 1162, 1, 0),
  (593, 0, 0, '又有人乱扔东西么？', 1162, 1, 0),
  (594, 0, 2, '又有人乱扔东西么？', 1162, 1, 0),
  (595, 0, 3, '唉！又逼小妖我出手！', 1162, 1, 0),
  (596, 0, 4, '欺负我头上没长毛么？', 1162, 1, 0),
  (597, 0, 5, '记得将这里打扫干净哦！', 1162, 1, 0),
  (598, 0, 6, '糟糕！又弄脏啦！', 1162, 1, 0),
  (599, 0, 0, '越是虚幻的越美丽，越是美丽的越伤人！', 1163, 1, 0),
  (6, 0, 2, '过来呀，小乖乖！', 1002, 1, 0),
  (60, 0, 0, '肚子又饿了……', 1014, 1, 0),
  (600, 0, 0, '谁那么狠心，伤害我的同伴？', 1163, 1, 0),
  (601, 0, 2, '遇见我是你美丽的错误！', 1163, 1, 0),
  (602, 0, 3, '没听过越是美丽的越伤人吗？咯咯！', 1163, 1, 0),
  (603, 0, 4, '我这么美丽，你忍心么？', 1163, 1, 0),
  (604, 0, 5, '别伤心哦，死在我手上是你美丽的宿命！', 1163, 1, 0),
  (605, 0, 6, '死亡也是一场幻觉！', 1163, 1, 0),
  (606, 0, 0, '啷里个啷～啷里个啷～', 1164, 1, 0),
  (607, 0, 0, '哥们并肩子上啊！', 1164, 1, 0),
  (608, 0, 2, '俺好像闻到了血的鲜味！啧啧！', 1164, 1, 0),
  (609, 0, 3, '新鲜人血的滋味真不错！啧啧！', 1164, 1, 0),
  (61, 0, 2, '有肥羊入口啦！', 1014, 1, 0),
  (610, 0, 4, '哎唷妈呀！', 1164, 1, 0),
  (611, 0, 5, '俺吸血霸王蚊的名头可不是白叫的！', 1164, 1, 0),
  (612, 0, 6, '这下亏大啦！', 1164, 1, 0),
  (613, 0, 0, '三兄弟中我最牛！不信你试试？', 1165, 1, 0),
  (614, 0, 2, '不要害怕哦！别跑哦！', 1165, 1, 0),
  (615, 0, 3, '不要害怕哦！别跑哦！', 1165, 1, 0),
  (616, 0, 4, '还好我有壳！', 1165, 1, 0),
  (617, 0, 5, '嘻嘻，原来比我还肉！', 1165, 1, 0),
  (618, 0, 6, '这下面子丢大啦！', 1165, 1, 0),
  (619, 0, 0, '我得意的笑～～我得意的笑～～', 1166, 1, 0),
  (62, 0, 3, '这家伙挺肥的，不错不错！', 1014, 1, 0),
  (620, 0, 2, '过来呀，小乖乖，陪我玩玩儿～', 1166, 1, 0),
  (621, 0, 3, '好玩吗？', 1166, 1, 0),
  (622, 0, 4, '好玩吗？', 1166, 1, 0),
  (623, 0, 5, '下次记得再来找我哦！', 1166, 1, 0),
  (624, 0, 6, '这下没得玩儿啦……', 1166, 1, 0),
  (625, 0, 0, '不要歧视六只脚的蜘蛛哦！', 1167, 1, 0),
  (626, 0, 2, '谁敢歧视我？谁！谁！', 1167, 1, 0),
  (627, 0, 3, '我强吧？强悍的人生不需要解释！', 1167, 1, 0),
  (628, 0, 4, '我强吧？强悍的人生不需要解释！', 1167, 1, 0),
  (629, 0, 5, '我强吧？强悍的人生不需要解释！', 1167, 1, 0),
  (63, 0, 4, '力气不小嘛！', 1014, 1, 0),
  (630, 0, 6, '强悍的人生也有脆弱的时候……', 1167, 1, 0),
  (631, 0, 0, '脑袋大不一定聪明，脚多不一定走得快！', 1168, 1, 0),
  (632, 0, 2, '到底是人怕虫还是虫怕人？', 1168, 1, 0),
  (633, 0, 3, '哇呀呀！好厉害呀！', 1168, 1, 0),
  (634, 0, 4, '哇呀呀！好厉害呀！', 1168, 1, 0),
  (635, 0, 5, '哇呀呀！好嘞！', 1168, 1, 0),
  (636, 0, 6, '哇呀呀！惨喽！', 1168, 1, 0),
  (637, 0, 0, '俺可不是普通的虫虫哦！', 1169, 1, 0),
  (638, 0, 2, '哈罗！', 1169, 1, 0),
  (639, 0, 3, '虫虫不怕你！', 1169, 1, 0),
  (64, 0, 5, '可以大餐一顿啦！', 1014, 1, 0),
  (640, 0, 4, '虫虫不怕你！', 1169, 1, 0),
  (641, 0, 5, '虫虫赢喽！', 1169, 1, 0),
  (642, 0, 6, '二十秒后又是一条好汉！', 1169, 1, 0),
  (643, 0, 0, '那些人都好坏坏的！', 1170, 1, 0),
  (644, 0, 2, '坏坏的家伙又来啦！', 1170, 1, 0),
  (645, 0, 3, '你好坏坏哦！', 1170, 1, 0),
  (646, 0, 4, '不要把我的样子和土豆比', 1170, 1, 0),
  (647, 0, 5, '好嘢！', 1170, 1, 0),
  (648, 0, 6, '你好坏坏哦！', 1170, 1, 0),
  (649, 0, 0, '谁能告诉我？谁会在乎我？', 1171, 1, 0),
  (65, 0, 6, '噢－－', 1014, 1, 0),
  (650, 0, 0, '请不要和我抢东西，谢谢！', 1171, 1, 0),
  (651, 0, 2, '你好！', 1171, 1, 0),
  (652, 0, 3, '不好意思哦！', 1171, 1, 0),
  (653, 0, 4, '不好意思哦！', 1171, 1, 0),
  (654, 0, 5, '糟糕！不小心把你打死啦，请你一定要谅解哦！', 1171, 1, 0),
  (655, 0, 6, '为什么？这是为什么？', 1171, 1, 0),
  (656, 0, 0, '兄弟姐妹们一起上啊！', 1172, 1, 0),
  (657, 0, 0, '我是高手我怕谁？', 1172, 1, 0)
INSERT INTO "gamedata"."ov_dialog" ("row_no", "reserve", "scene", "desc_", "mon_id", "speak_grp_1_4", "reserved") VALUES
  (658, 0, 2, '我是高手我怕谁？', 1172, 1, 0),
  (659, 0, 3, '我好厉害哦！我太崇拜自己啦！', 1172, 1, 0),
